/** Captures the installed UI with an isolated, explicitly labelled manual demo project. */
final class ManualScreens {
    static Instrumentation host;static int count;
    interface Task{void run()throws Exception;}
    static void ui(Task task){Throwable[] failure={null};host.runOnMainSync(()->{try{task.run();}catch(Throwable e){failure[0]=e;}});if(failure[0]!=null)throw new RuntimeException(failure[0]);}
    static Object get(Object target,String name)throws Exception{Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(target);}
    static void set(Object target,String name,Object value)throws Exception{Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);f.set(target,value);}
    static void call(Object target,String name)throws Exception{Method m=target.getClass().getDeclaredMethod(name);m.setAccessible(true);m.invoke(target);}
    static void call(Object target,String name,String value)throws Exception{Method m=target.getClass().getDeclaredMethod(name,String.class);m.setAccessible(true);m.invoke(target,value);}
    static void shot(String name)throws Exception{Thread.sleep(650);Bitmap bitmap=host.getUiAutomation().takeScreenshot();if(bitmap==null)throw new IOException("Screenshot unavailable: "+name);File directory=host.getTargetContext().getExternalFilesDir("manual-screens");if(!directory.exists()&&!directory.mkdirs())throw new IOException("Screenshot directory unavailable");try(FileOutputStream out=new FileOutputStream(new File(directory,name+".png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();count++;}
    static void back(){host.sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);host.waitForIdleSync();}
    static void dialog(Object owner,String method,String name)throws Exception{ui(()->call(owner,method));shot(name);back();}
    static void run(Instrumentation instrumentation,Bundle result)throws Exception{
        host=instrumentation;MainActivity main=(MainActivity)host.startActivitySync(new Intent(host.getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));shot("01-home");
        ui(()->call(main,"chooseRole","camera"));Thread.sleep(2200);shot("02-camera");ui(()->call(get(main,"cameraControls"),"select","iso"));shot("03-iso");
        dialog(main,"recordingSetup","04-shooting-setup");dialog(main,"preflight","05-preflight");dialog(main,"countdownSettings","06-countdown");dialog(main,"previewTools","07-guides");dialog(main,"videoSetup","08-quality");dialog(main,"microphoneSetup","09-microphone");dialog(main,"eventTools","10-event-slate");
        ui(()->{set(main,"scriptVisible",true);PrompterView p=(PrompterView)get(main,"prompter");JSONObject script=p.snapshot();script.put("script","Welcome to my story.\n\nToday I will show you three simple ways to film with confidence.\n\nFirst, check your sound and framing.\n\nNext, take your time and speak naturally.\n\nFinally, review your take before you pack up.");script.put("title","Manual demo script");script.put("revision",java.util.UUID.randomUUID().toString());script.put("playing",false);p.apply(script);call(main,"arrange");});shot("11-prompter");ui(()->call(get(main,"prompter"),"edit"));shot("12-script-editor");back();
        ui(()->call(main,"chooseRole","monitor"));shot("13-monitor-connect");back();ui(()->call(main,"cleanup"));
        ScreenRecordingActivity screen=(ScreenRecordingActivity)host.startActivitySync(new Intent(host.getTargetContext(),ScreenRecordingActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ui(()->{Switch face=(Switch)get(screen,"face");if(!face.isChecked())face.performClick();});shot("14-screen-recording");ui(screen::finish);host.waitForIdleSync();
        PublishActivity publish=(PublishActivity)host.startActivitySync(new Intent(host.getTargetContext(),PublishActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));shot("15-publish-queue");ui(()->{set(publish,"section","Accounts");call(publish,"render");});shot("16-publish-accounts");ui(()->{set(publish,"section","Calendar");call(publish,"render");});shot("17-publish-calendar");ui(()->call(publish,"newComposer"));shot("18-post-composer");back();ui(publish::finish);host.waitForIdleSync();
        EditorActivity editor=(EditorActivity)host.startActivitySync(new Intent(host.getTargetContext(),EditorActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));shot("19-studio");ui(()->call(editor,"startNewProject"));shot("20-empty-project");
        final EditorProject[] project={null};final File[] artwork={null},audio={null};
        ui(()->{project[0]=(EditorProject)get(editor,"project");project[0].name="Manual demonstration";Method read=EditorActivity.class.getDeclaredMethod("readClip",Uri.class);read.setAccessible(true);EditorProject.Clip source=(EditorProject.Clip)read.invoke(editor,Uri.parse("content://media/external/video/media/36533"));source.name="Demo take A";project[0].clips.add(source);EditorProject.Clip second=source.copy();second.name="Demo take B";second.timelineAt=-1;project[0].clips.add(second);project[0].aspect=1;project[0].height=720;
            Bitmap b=Bitmap.createBitmap(720,1280,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);Paint paint=new Paint(3);paint.setShader(new LinearGradient(0,0,720,1280,new int[]{0xff132a39,0xff274938,0xff101d2a},null,Shader.TileMode.CLAMP));canvas.drawRect(0,0,720,1280,paint);paint.setShader(null);paint.setColor(0xffffc857);canvas.drawCircle(550,260,160,paint);paint.setColor(0xff132a39);canvas.drawCircle(550,260,130,paint);paint.setColor(Color.WHITE);paint.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));paint.setTextSize(66);canvas.drawText("TELL YOUR",55,650,paint);canvas.drawText("STORY.",55,730,paint);paint.setTextSize(24);paint.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));canvas.drawText("A Solo Camera editing example",55,800,paint);paint.setColor(0xffffc857);canvas.drawRect(55,850,300,857,paint);artwork[0]=new File(editor.getFilesDir(),"manual-demo-art.png");try(FileOutputStream out=new FileOutputStream(artwork[0])){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();
            EditorProject.Caption photo=new EditorProject.Caption();photo.type="Image";photo.style=source.copy();photo.style.imageUri=artwork[0].getAbsolutePath();photo.style.text="";photo.style.fillFrame=true;photo.at=0;photo.end=project[0].duration();project[0].captions.add(photo);
            EditorProject.Caption text=new EditorProject.Caption();text.style=source.copy();text.style.text="CREATE WITH CONFIDENCE";text.style.textColor=0xffffc857;text.style.textSize=52;text.style.bold=true;text.style.textPlaced=true;text.style.textY=-.55;text.at=0;text.end=project[0].duration();text.track=0;project[0].captions.add(text);
            audio[0]=new File(editor.getFilesDir(),"manual-demo.wav");int samples=48000*6;try(java.io.DataOutputStream out=new java.io.DataOutputStream(new FileOutputStream(audio[0]))){out.writeBytes("RIFF");out.writeInt(Integer.reverseBytes(36+samples*2));out.writeBytes("WAVEfmt ");out.writeInt(Integer.reverseBytes(16));out.writeShort(Short.reverseBytes((short)1));out.writeShort(Short.reverseBytes((short)1));out.writeInt(Integer.reverseBytes(48000));out.writeInt(Integer.reverseBytes(96000));out.writeShort(Short.reverseBytes((short)2));out.writeShort(Short.reverseBytes((short)16));out.writeBytes("data");out.writeInt(Integer.reverseBytes(samples*2));for(int i=0;i<samples;i++)out.writeShort(Short.reverseBytes((short)(Math.sin(i*440*2*Math.PI/48000)*2400*(.5+.5*Math.sin(i*2*Math.PI/12000)))));}
            EditorProject.Audio sound=new EditorProject.Audio();sound.uri=audio[0].getAbsolutePath();sound.name="Demo soundtrack";sound.duration=sound.end=6000;project[0].audios.add(sound);set(editor,"position",800L);call(editor,"showEditor");});Thread.sleep(1200);shot("21-editor");dialog(editor,"mediaPanel","22-media-library");dialog(editor,"snapSettingsDialog","23-snapping");dialog(editor,"selectionMenu","24-selection");dialog(editor,"creatorTools","25-creator-tools");
        ui(()->{set(editor,"selectedCaption",1);set(editor,"selectedTrack","Text");call(editor,"selectTool","Text");});shot("26-text-tools");ui(()->{Method reveal=EditorActivity.class.getDeclaredMethod("revealPicker",EditorProject.Clip.class);reveal.setAccessible(true);reveal.invoke(editor,project[0].captions.get(1).style);});shot("27-reveals");back();
        ui(()->{set(editor,"selectedCaption",-1);set(editor,"selectedTrack","Video");set(editor,"selected",0);call(editor,"selectTool","Adjust");});shot("28-adjust-curves");ui(()->call(editor,"selectTool","Mask"));shot("29-mask");ui(()->call(editor,"selectTool","Animate"));shot("30-animations");ui(()->call(editor,"addMotionKey"));ui(()->call(editor,"selectTool","Keyframes"));shot("31-keyframes");ui(()->{Method transition=EditorActivity.class.getDeclaredMethod("transitionDialog",int.class);transition.setAccessible(true);transition.invoke(editor,1);});shot("32-transitions");back();
        ui(()->call(editor,"showOverlayImportScreen"));shot("33-add-overlay");ui(()->call(editor,"returnToEditor"));ui(()->call(editor,"showAudioImportScreen"));shot("34-add-audio");ui(()->call(editor,"returnToEditor"));ui(()->{set(editor,"selectedTrack","Audio");set(editor,"selectedAudio",0);call(editor,"showEditor");});shot("35-audio-track");dialog(editor,"duckingSettings","36-ducking");dialog(editor,"recordVoiceover","37-voiceover");ui(()->{set(editor,"selectedTrack","Video");set(editor,"selected",0);});dialog(editor,"syncCalibration","38-sync");ui(()->call(editor,"showAiToolsScreen"));shot("39-ai-tools");ui(()->call(editor,"returnToEditor"));dialog(editor,"exportSetup","40-export-video");dialog(editor,"audioFormatDialog","41-export-audio");dialog(editor,"creatorTemplates","42-templates");ui(()->call(editor,"showLibrary"));shot("43-project-library");
        String id=project[0].id;ui(editor::finish);host.waitForIdleSync();new File(EditorProject.directory(host.getTargetContext()),id+".json").delete();artwork[0].delete();audio[0].delete();ui(main::finish);result.putInt("screenshots",count);result.putString("directory",host.getTargetContext().getExternalFilesDir("manual-screens").getAbsolutePath());
    }
}
